let FLAT = [];
DATA.forEach((sec,si)=>{
  sec.subs.forEach((sub,bi)=>{
    sub.items.forEach((it,ii)=>{
      const [brand,generic,cls,flags,moa] = it;
      const fl = (flags||"").split(",").filter(Boolean);
      FLAT.push({
        id: si+"-"+bi+"-"+ii,
        section: sec.t, sub: sub.n,
        brand, generic, cls, moa: moa||"",
        er: fl.includes("er"),
        high: fl.includes("high"),
        lasa: fl.find(f=>f.startsWith("lasa"))||null,
        g6pd: fl.includes("g6pd") ? "avoid" : (fl.includes("g6pdc") ? "caution" : null),
        hla: fl.find(f=>f.startsWith("hla"))||null,
        pgx: fl.includes("cyp2c19") ? "cyp2c19" : null,
        struct: STRUCTS[brand] || null,
        clinical: CLINICAL[brand] || null,
        nhi: NHI_LINKS[brand] || null
      });
    });
  });
});

