/* ============ STATE / LOCALSTORAGE ============ */
const LS_KEY = "pharmReviewState_v1";
function loadState(){
  try{ return JSON.parse(localStorage.getItem(LS_KEY)) || {mastered:{}, seen:{}}; }
  catch(e){ return {mastered:{}, seen:{}}; }
}
function saveState(s){
  try{ localStorage.setItem(LS_KEY, JSON.stringify(s)); }catch(e){}
}
let STATE = loadState();

let collapsedSections = new Set();
let reviewScope = "all"; // section title or "all" or "flagged"
let reviewQueue = [];
let reviewIdx = 0;
let curCard = null;

/* ============ TAB SWITCH ============ */
const views = {browse:document.getElementById("view-browse"), review:document.getElementById("view-review"), sop:document.getElementById("view-sop")};
document.querySelectorAll(".tab-btn").forEach(btn=>{
  btn.addEventListener("click",()=>{
    document.querySelectorAll(".tab-btn").forEach(b=>b.classList.remove("active"));
    btn.classList.add("active");
    Object.entries(views).forEach(([k,el])=>el.classList.toggle("active", k===btn.dataset.tab));
    document.getElementById("searchWrap").style.display = btn.dataset.tab==="browse" ? "flex":"none";
    if(btn.dataset.tab==="review" && !curCard) startReview();
  });
});
views.browse.classList.add("active");

/* ============ BROWSE VIEW ============ */
function renderBrowse(filter){
  const q = (filter||"").trim().toLowerCase();
  const el = views.browse;
  el.innerHTML = "";
  let totalShown = 0;

  DATA.forEach((sec,si)=>{
    const secItems = [];
    sec.subs.forEach((sub,bi)=>{
      const matched = sub.items.filter(it=>{
        if(!q) return true;
        const [brand,generic,cls] = it;
        return (brand+" "+generic+" "+cls+" "+sec.t+" "+sub.n).toLowerCase().includes(q);
      });
      if(matched.length) secItems.push({sub, matched});
    });
    if(!secItems.length) return;

    const block = document.createElement("div");
    block.className = "section-block" + (collapsedSections.has(si) && !q ? " collapsed":"");
    const count = secItems.reduce((a,s)=>a+s.matched.length,0);
    totalShown += count;

    const head = document.createElement("div");
    head.className = "section-head";
    head.innerHTML = `<span class="section-title">${sec.t}</span>
      <span style="display:flex;align-items:center;gap:8px;">
        <span class="section-count">${count}</span>
        <svg class="chev" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 9l6 6 6-6"/></svg>
      </span>`;
    head.addEventListener("click",()=>{
      if(collapsedSections.has(si)) collapsedSections.delete(si); else collapsedSections.add(si);
      renderBrowse(document.getElementById("searchInput").value);
    });
    block.appendChild(head);

    const body = document.createElement("div");
    body.className = "section-body";
    secItems.forEach(({sub,matched})=>{
      if(sec.subs.length>1){
        const lbl = document.createElement("div");
        lbl.className = "subgroup-label";
        lbl.textContent = sub.n;
        body.appendChild(lbl);
      }
      matched.forEach(it=>{
        const [brand,generic,cls,flags] = it;
        const fl = (flags||"").split(",").filter(Boolean);
        const card = document.createElement("div");
        card.className = "drug-card";
        card.innerHTML = `
          <div class="drug-top">
            <div class="drug-brand">${brand}</div>
            <span class="drug-tag${fl.includes('high')?' tag-danger':''}">${cls.split("（")[0].slice(0,10)}</span>
          </div>
          <div class="drug-generic">${generic}</div>
          <div class="drug-badges">
            ${fl.includes('high')?'<span class="badge b-high">⚠ 高警訊</span>':''}
            ${fl.includes('er')?'<span class="badge b-er">緩釋 不可磨粉</span>':''}
            ${fl.find(f=>f.startsWith('lasa'))?'<span class="badge b-lasa">LASA 易混淆</span>':''}
            ${fl.includes('g6pd')?'<span class="badge b-g6pd">🫘 蠶豆症禁忌</span>':''}
            ${fl.includes('g6pdc')?'<span class="badge b-g6pd">🫘 蠶豆症謹慎</span>':''}
            ${fl.find(f=>f.startsWith('hla'))?'<span class="badge b-hla">🧬 HLA警訊</span>':''}
          </div>
          <div class="tap-affordance">點卡片看機轉／結構／衛教 ›</div>`;
        card.addEventListener("click",()=>openDetail(brand));
        body.appendChild(card);
      });
    });
    block.appendChild(body);
    el.appendChild(block);
  });

  document.getElementById("searchCount").textContent = q ? totalShown+" 筆" : "";
  if(totalShown===0){
    el.innerHTML = `<div class="empty-state"><div class="big">🔍</div>找不到符合「${filter}」的藥品</div>`;
  }
}
document.getElementById("searchInput").addEventListener("input", e=>renderBrowse(e.target.value));
renderBrowse("");

/* ============ DETAIL SHEET ============ */
function findLasaPair(brand){
  return LASA_PAIRS.find(p=>brand.includes(p.a.split(" ")[0]) || p.a.includes(brand.split(" ")[0]) || brand.includes(p.b.split(" ")[0]) || p.b.includes(brand.split(" ")[0]));
}
