function closeDetail(){
  document.getElementById("detailSheet").classList.remove("open");
  document.getElementById("sheetBackdrop").classList.remove("open");
  document.body.style.overflow = "";
}
document.getElementById("sheetBackdrop").addEventListener("click", closeDetail);

/* ============ REVIEW VIEW ============ */
function buildQueue(){
  let pool = FLAT.filter(d=>!STATE.mastered[d.id]);
  if(reviewScope==="flagged") pool = pool.filter(d=>d.high || d.lasa || d.er);
  else if(reviewScope!=="all") pool = pool.filter(d=>d.section===reviewScope);
  if(pool.length===0) pool = (reviewScope==="flagged" ? FLAT.filter(d=>d.high||d.lasa||d.er) : (reviewScope==="all"?FLAT:FLAT.filter(d=>d.section===reviewScope)));
  // shuffle
  for(let i=pool.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [pool[i],pool[j]]=[pool[j],pool[i]]; }
  return pool;
}
function masteredCount(){ return Object.keys(STATE.mastered).length; }

function renderReviewShell(){
  const el = views.review;
  el.innerHTML = `
    <div class="review-wrap">
      <div class="review-stats">
        <div class="stat-tile"><div class="stat-num mono" id="statMastered">0</div><div class="stat-label">已熟悉</div></div>
        <div class="stat-tile"><div class="stat-num mono" id="statRemain">0</div><div class="stat-label">待複習</div></div>
        <div class="stat-tile"><div class="stat-num mono">${FLAT.length}</div><div class="stat-label">總藥品數</div></div>
      </div>
      <div class="review-setup">
        <div class="chip-row" id="scopeChips"></div>
      </div>
      <div class="flashcard-outer">
        <div class="flashcard" id="flashcard">
          <div class="face front">
            <div class="eyebrow">商品名 BRAND</div>
            <div class="headline" id="cardFront">—</div>
            <div class="tap-hint">點卡片看學名與分類 →</div>
          </div>
          <div class="face back" id="cardBackFace">
            <div class="eyebrow">學名 GENERIC ・ 分類</div>
            <div class="headline mono" id="cardBackGeneric" style="font-size:18px;">—</div>
            <div class="sub" id="cardBackCls">—</div>
            <div class="flags" id="cardFlags"></div>
            <div class="sub" id="cardMoa" style="font-size:11.5px; margin-top:8px; line-height:1.5; max-height:64px; overflow-y:auto;"></div>
          </div>
        </div>
      </div>
      <div class="review-actions">
        <button class="rbtn again" id="btnAgain">還不熟</button>
        <button class="rbtn skip" id="btnSkip">跳過</button>
        <button class="rbtn known" id="btnKnown">已熟悉 ✓</button>
      </div>
    </div>`;

  const chipRow = document.getElementById("scopeChips");
  const scopes = [["all","全部"],["flagged","⚠ 高警訊/LASA/緩釋"],...DATA.map(s=>[s.t,s.t])];
  scopes.forEach(([val,label])=>{
    const chip = document.createElement("div");
    chip.className = "chip"+(reviewScope===val?" active":"");
    chip.textContent = label;
    chip.addEventListener("click",()=>{ reviewScope=val; startReview(); });
    chipRow.appendChild(chip);
  });

  document.getElementById("flashcard").addEventListener("click", flipCard);
  document.getElementById("btnAgain").addEventListener("click",(e)=>{e.stopPropagation(); nextCard(false);});
  document.getElementById("btnSkip").addEventListener("click",(e)=>{e.stopPropagation(); nextCard(null);});
  document.getElementById("btnKnown").addEventListener("click",(e)=>{e.stopPropagation(); nextCard(true);});
  updateStats();
}
function updateStats(){
  const m = document.getElementById("statMastered");
  const r = document.getElementById("statRemain");
  if(m) m.textContent = masteredCount();
  if(r) r.textContent = FLAT.length - masteredCount();
}
function flipCard(){
  document.getElementById("flashcard").classList.toggle("flipped");
}
function showCard(){
  if(reviewIdx >= reviewQueue.length){ reviewQueue = buildQueue(); reviewIdx = 0; }
  if(reviewQueue.length===0) return;
  curCard = reviewQueue[reviewIdx];
  document.getElementById("flashcard").classList.remove("flipped");
  document.getElementById("cardFront").textContent = curCard.brand;
  document.getElementById("cardBackGeneric").textContent = curCard.generic;
  document.getElementById("cardBackCls").textContent = curCard.cls + "　·　" + curCard.section;
  const flagsEl = document.getElementById("cardFlags");
  flagsEl.innerHTML = (curCard.high?'<span class="badge b-high">⚠ 高警訊</span>':"") +
    (curCard.er?'<span class="badge b-er">緩釋 不可磨粉</span>':"") +
    (curCard.lasa?'<span class="badge b-lasa">LASA 易混淆</span>':"") +
    (curCard.g6pd?'<span class="badge b-g6pd">🫘 蠶豆症</span>':"") +
    (curCard.hla?'<span class="badge b-hla">🧬 HLA</span>':"");
  document.getElementById("cardMoa").textContent = curCard.moa || "";
}
function nextCard(result){
  if(curCard){
    if(result===true) STATE.mastered[curCard.id]=1;
    if(result===false) delete STATE.mastered[curCard.id];
    saveState(STATE);
  }
  reviewIdx++;
  updateStats();
  showCard();
}
function startReview(){
  renderReviewShell();
  reviewQueue = buildQueue();
  reviewIdx = 0;
  showCard();
}

